INSERT INTO `cms_events` VALUES (1,'New Academic Year Orientation','new-academic-year-orientation-2026','Welcome ceremony and orientation for new and returning students for the 2026 academic year.','Welcome ceremony for all students','2026-02-01',NULL,NULL,NULL,'ISNM Main Campus','academic',NULL,NULL,NULL,0,0,1,NULL,'2026-07-14 07:12:37','2026-07-14 07:12:37'),(2,'International Nurses Day Celebration','international-nurses-day-2026','Annual celebration of International Nurses Day with guest speakers, exhibitions, and awards.','Celebrating nursing excellence','2026-05-12',NULL,NULL,NULL,'ISNM Auditorium','ceremony',NULL,NULL,NULL,0,0,1,NULL,'2026-07-14 07:12:37','2026-07-14 07:12:37'),(3,'Clinical Skills Workshop','clinical-skills-workshop-2026','Hands-on workshop for nursing students on advanced clinical skills and patient care techniques.','Advanced clinical skills training','2026-06-15',NULL,NULL,NULL,'ISNM Skills Laboratory','workshop',NULL,NULL,NULL,0,0,1,NULL,'2026-07-14 07:12:37','2026-07-14 07:12:37');
