INSERT INTO `cms_testimonials` VALUES (1,'Sarah Nambogo','Registered Nurse, Mulago Hospital',NULL,'alumni','ISNM gave me the foundation I needed to become a competent nurse. The clinical training and dedicated faculty prepared me for the real healthcare challenges.',5,1,1,1,'2026-07-14 07:12:04'),(2,'James Ochieng','Midwife, Iganga Health Center IV',NULL,'alumni','The Certificate in Midwifery program at ISNM was transformative. I now serve my community with confidence and professional expertise.',5,1,1,2,'2026-07-14 07:12:04'),(3,'Grace Nakamya','Student, Diploma in Nursing',NULL,'student','Choosing ISNM was the best decision of my life. The modern facilities, experienced lecturers, and supportive learning environment make every day worthwhile.',5,1,1,3,'2026-07-14 07:12:04'),(4,'Dr. Moses Wambamba','Medical Director, Iganga Hospital',NULL,'partner','ISNM graduates consistently demonstrate clinical excellence and compassionate care. We are proud to partner with this exceptional institution.',5,1,1,4,'2026-07-14 07:12:04');
