INSERT INTO `cms_content_blocks` VALUES (1,1,'welcome','text','Welcome to Iganga School of Nursing and Midwifery','Established to provide quality nursing and midwifery education in Uganda and the region.','<p>Iganga School of Nursing and Midwifery (ISNM) is a premier healthcare education institution dedicated to training competent, compassionate, and skilled nurses and midwives. Located in Iganga, Eastern Uganda, we have been at the forefront of healthcare education since 1997.</p><p>Our programs are designed to equip students with the knowledge, skills, and values needed to provide quality healthcare services in diverse settings.</p>',NULL,'fade-up',NULL,NULL,1,1,NULL,'2026-07-14 07:12:48','2026-07-14 07:12:48'),(2,1,'stats','stats','Our Impact in Numbers','Making a difference in healthcare education',NULL,NULL,'fade-up',NULL,NULL,2,1,NULL,'2026-07-14 07:12:48','2026-07-14 07:12:48'),(3,1,'why_choose','cards','Why Choose ISNM','Discover what makes us the preferred choice for healthcare education',NULL,NULL,'fade-up',NULL,NULL,3,1,NULL,'2026-07-14 07:12:48','2026-07-14 07:12:48'),(4,1,'cta','cta','Ready to Start Your Journey?','Join thousands of healthcare professionals trained at ISNM',NULL,NULL,'fade-up',NULL,NULL,10,1,NULL,'2026-07-14 07:12:48','2026-07-14 07:12:48');
